async function filesUnder(directory){
  const absolute_directory=resolve(projectRoot,directory),entries=await readdir(absolute_directory,{withFileTypes:true});
  const nested=await Promise.all(entries.map(async entry=>{
    const path=relative(projectRoot,resolve(absolute_directory,entry.name)).replaceAll('\\','/');
    return entry.isDirectory()?filesUnder(path):[path];
  }));
  return nested.flat();
}
